const reponse = $input.first().json.text || $input.first().json.content;

// Extraire le JSON de la réponse
let data;
try {
  // Chercher un bloc JSON dans la réponse
  const jsonMatch = reponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    data = JSON.parse(jsonMatch[0]);
  } else {
    data = { resume_marche: reponse, actions: [], points_vigilance: [] };
  }
} catch(e) {
  data = { resume_marche: reponse, actions: [], points_vigilance: [], erreur_parsing: e.message };
}

return [{ json: data }];

// Prépare les mises à jour pour chaque action analysée
const data = $node['Parser réponse JSON agent'].json;
const actions = data.actions || [];
const updates = [];

for (const action of actions) {
  if (action.ticker) {
    updates.push({
      ticker: action.ticker,
      prix_actuel: action.prix_estime || '',
      variation_jour: action.variation_estimee || '',
      note_analyste: action.note || '',
      commentaire: action.commentaire || '',
      derniere_maj: new Date().toISOString()
    });
  }
}

return updates.map(u => ({ json: u }));

const data = $node['Parser réponse JSON agent'].json;
const date = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const actions = (data.actions || []).slice(0, 5);
const notesEmojis = {
  'eviter': '🔴',
  'surveiller': '🟡',
  'interessante': '🟢',
  'achat_progressif': '✅',
  'achat_progressif_possible': '✅'
};

let actionsTexte = actions.map(a => {
  const emoji = notesEmojis[a.note] || '⚪';
  return `${emoji} *${a.ticker}* — ${a.note || '?'}: ${a.commentaire || ''}`;
}).join('\n');

if (!actionsTexte) actionsTexte = '_Aucune donnée disponible_';

const vigilance = (data.points_vigilance || []).slice(0, 3).map(p => `⚠️ ${p}`).join('\n');

const message = `📊 *Veille BRVM — ${date}*

📝 *Résumé du marché :*
${(data.resume_marche || 'Pas de données').substring(0, 600)}

🔍 *Watchlist (top 5) :*
${actionsTexte}

${vigilance ? '⚠️ *Points de vigilance :*\n' + vigilance : ''}

─────────────────
💡 _Ceci est une analyse informative. Aucune décision d'achat ne doit être prise sans votre propre analyse._
🏦 _Investisseur Afrique BRVM_`;

return [{ json: { message } }];
